console.log('Start');

setTimeout(() => {
  console.log('Timeout after 10ms');
}, 10);

console.log('After scheduling timeout');

let count = 0;
const interval = setInterval(() => {
  count++;
  console.log('Tick ' + count);
  if (count >= 3) {
    clearInterval(interval);
  }
}, 5);

setTimeout(() => {
  console.log('All done!');
}, 30);
